import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const tradeTokenApi = createApi({
    reducerPath: 'tradeTokenApi',
    tagTypes: ['tradeTokenServer'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getTradeTokenServer: builder.query({
            query: ({ platform_uuid, pin_code }) => ({
                url: `/trade-tokens/${platform_uuid}`,
                method: RequestMethods.POST,
                body: { pin_code },
            }),
            providesTags: ['tradeTokenServer'],
        }),
        createTradeTokenServer: builder.mutation({
            query: (body) => ({
                url: '/trade-tokens',
                method: RequestMethods.POST,
                body,
            }),
            invalidatesTags: ['tradeTokenServer'],
        }),
        revokeTradeTokenServer: builder.mutation({
            query: ({ platform_uuid }) => ({
                url: `/trade-tokens/${platform_uuid}`,
                method: RequestMethods.DELETE,
            }),
            invalidatesTags: ['tradeTokenServer'],
        }),
    }),
});
export const { useLazyGetTradeTokenServerQuery, useCreateTradeTokenServerMutation, useRevokeTradeTokenServerMutation } = tradeTokenApi;
