import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { buildSearchParams } from '06_shared/utils/buildSearchParams';
export const analysisApi = createApi({
    reducerPath: 'analysisApi',
    tagTypes: ['analysis'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getAnalysis: builder.query({
            query: (params) => ({
                url: `/analysis?${buildSearchParams(params)}`,
                method: RequestMethods.GET,
            }),
            providesTags: ['analysis'],
        }),
    }),
});
export const { useGetAnalysisQuery, } = analysisApi;
