export function parseApiError(error) {
    if (!error)
        return 'Unknown error';
    if (typeof error === 'object' && error !== null && 'status' in error && 'data' in error) {
        const fetchError = error;
        if (fetchError.data && typeof fetchError.data === 'object' && 'detail' in fetchError.data) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            return String(fetchError.data.detail);
        }
        return `HTTP error ${fetchError.status}`;
    }
    if (typeof error === 'object' && error !== null && 'message' in error) {
        return String(error.message);
    }
    return 'Unknown error';
}
