import { createSlice, } from '@reduxjs/toolkit';
import { TradeStatusEnum, } from '../types/tradeSchema';
const initialState = {
    trade_by_uuid_dict: {},
    trade_uuid_by_symbol_uuid_dict: {},
    current_pnl: 0,
    possible_loss: 0,
};
export const tradeSlice = createSlice({
    name: 'trade',
    initialState,
    reducers: {
        setTradeList: (state, action) => {
            state.trade_by_uuid_dict = {};
            state.trade_uuid_by_symbol_uuid_dict = {};
            let current_pnl = 0;
            let possible_loss = 0;
            action.payload.forEach(item => {
                state.trade_by_uuid_dict[item.trade_uuid] = item;
                state.trade_uuid_by_symbol_uuid_dict[item.symbol_uuid] = item.trade_uuid;
                current_pnl = current_pnl + item.trade_pnl_current;
                possible_loss = possible_loss
                    + item.trade_margin * item.trade_treiling_stop_percent_current * 0.01;
            });
            state.current_pnl = current_pnl;
            state.possible_loss = possible_loss;
        },
        updateTradeAfterCalculate: (state, action) => {
            const old_trade = state.trade_by_uuid_dict[action.payload.trade_uuid];
            const new_trade = action.payload.trade_update_calculated;
            const current_pnl = state.current_pnl
                - old_trade.trade_pnl_current
                + new_trade.trade_pnl_current;
            const possible_loss = state.possible_loss
                - (old_trade.trade_margin * old_trade.trade_treiling_stop_percent_current * 0.01)
                + (old_trade.trade_margin * new_trade.trade_treiling_stop_percent_current * 0.01);
            state.trade_by_uuid_dict[action.payload.trade_uuid] = {
                ...old_trade,
                ...new_trade,
            };
            state.current_pnl = current_pnl;
            state.possible_loss = possible_loss;
        },
        updateTradeAfterSignalItem: (state, action) => {
            const trade_uuid = state.trade_uuid_by_symbol_uuid_dict[action.payload.symbol_uuid];
            const trade_item = state.trade_by_uuid_dict[trade_uuid];
            if (!trade_item)
                return;
            const trade_ui_status = action.payload.signal_direction_created === trade_item.trade_direction
                ? TradeStatusEnum.DIRECTION_SIGNAL
                : TradeStatusEnum.REVERSE_SIGNAL;
            state.trade_by_uuid_dict[trade_uuid] = {
                ...trade_item,
                trade_ui_status,
            };
        },
        updateTradeStatuses: (state, action) => {
            state.trade_by_uuid_dict[action.payload.trade_uuid] = {
                ...state.trade_by_uuid_dict[action.payload.trade_uuid],
                trade_status: action.payload.trade_status,
                trade_ui_status: action.payload.trade_ui_status,
            };
        },
        resetTradeSlice() {
            return initialState;
        },
    }
});
export const { actions: tradeActions } = tradeSlice;
export const { reducer: tradeReducer } = tradeSlice;
