import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { statisticTradeByMonthActions } from '../../model/slice/statisticTradeByMonthSlice';
export const statisticTradeByMonthApi = createApi({
    reducerPath: 'statisticTradeByMonthApi',
    tagTypes: ['statisticTradeByMonth'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getStatisticTradeByMonth: builder.query({
            query: () => ({
                url: '/public/statistics/monthly',
                method: RequestMethods.GET,
            }),
            providesTags: ['statisticTradeByMonth'],
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    if (!data?.result)
                        return;
                    dispatch(statisticTradeByMonthActions.setStatisticTradeByMonth(data.result));
                }
                catch (e) {
                    console.error('Error in queryFulfilled getStatisticTradeByMonth', e);
                }
            },
        }),
    }),
});
export const { useGetStatisticTradeByMonthQuery, } = statisticTradeByMonthApi;
