import { createSlice, } from '@reduxjs/toolkit';
const initialState = {
    trade_token_dict: {},
};
export const tradeTokenSlice = createSlice({
    name: 'tradeToken',
    initialState,
    reducers: {
        setTradeToken: (state, action) => {
            state.trade_token_dict[action.payload.platform_uuid] = action.payload;
        },
        removeTradeToken: (state, action) => {
            delete state.trade_token_dict[action.payload];
        },
        resetTradeTokenSlice() {
            return initialState;
        },
    }
});
export const { actions: tradeTokenActions } = tradeTokenSlice;
export const { reducer: tradeTokenReducer } = tradeTokenSlice;
