import { RequestMethods, WSEventEnum } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { websocketTransport } from '06_shared/lib/websocket';
import { createApi } from '@reduxjs/toolkit/query/react';
import { bitcoinPublicActions } from '../slice/bitcoinPublicSlice';
export const bitcoinPublicInformationApi = createApi({
    reducerPath: 'bitcoinPublicInformationApi',
    tagTypes: ['bitcoinPublicInformation', 'bitcoinPublicTrendData'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getBitcoinPublicInformation: builder.query({
            query: () => ({
                url: '/public/bitcoin',
                method: RequestMethods.GET,
            }),
            providesTags: ['bitcoinPublicInformation'],
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    dispatch(bitcoinPublicActions.setBitcoinPublicInformation(data.result ?? undefined));
                }
                catch (e) {
                    console.error('Error in queryFulfilled getBitcoinPublicInformation', e);
                }
            },
            // Сокет лише доповнює дані цього ж запиту, тож підписка живе рівно
            // стільки, скільки в query є хоч один передплатник — окремий ефект
            // в UI не потрібен.
            async onCacheEntryAdded(arg, { dispatch, cacheDataLoaded, cacheEntryRemoved }) {
                try {
                    await cacheDataLoaded;
                }
                catch {
                    return;
                }
                const unsubscribe = websocketTransport.on(WSEventEnum.BITCOIN_PUBLIC_INFORMATION_FROM_CORE, (message) => {
                    const payload = message;
                    dispatch(bitcoinPublicActions.setBitcoinPublicInformation(payload.bitcoin_public_information));
                });
                await cacheEntryRemoved;
                unsubscribe();
            },
        }),
        getBitcoinPublicTrendData: builder.query({
            query: () => ({
                url: '/public/bitcoin/trend',
                method: RequestMethods.GET,
            }),
            providesTags: ['bitcoinPublicTrendData'],
        }),
    }),
});
export const { useGetBitcoinPublicInformationQuery, useGetBitcoinPublicTrendDataQuery, } = bitcoinPublicInformationApi;
