import { RequestMethods, } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { TradeStatusEnum, } from '../types/tradeSchema';
import { tradeActions } from '../slice/tradeSlice';
import { buildSearchParams } from '06_shared/utils/buildSearchParams';
export const tradeApi = createApi({
    reducerPath: 'tradeApi',
    tagTypes: ['tradeList', 'tradeTrendData'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getTradeList: builder.query({
            query: () => ({
                url: `/trades?${buildSearchParams({
                    trade_statuses: [TradeStatusEnum.OPEN],
                    limit: -1,
                })}`,
                method: RequestMethods.GET,
            }),
            providesTags: ['tradeList'],
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    dispatch(tradeActions.setTradeList(data.result?.items || []));
                }
                catch (e) {
                    console.error('Error in queryFulfilled getTradeList', e);
                }
            },
        }),
        getTradeTrendData: builder.query({
            query: (trade_uuid) => ({
                url: `/trades/${trade_uuid}/trend`,
                method: RequestMethods.GET,
            }),
            providesTags: ['tradeTrendData'],
        }),
        closeTradeServer: builder.mutation({
            query: ({ trade_uuid, ...body }) => ({
                url: `/trades/server/${trade_uuid}/close`,
                method: RequestMethods.POST,
                body,
            }),
        }),
        closeTradeClient: builder.mutation({
            query: ({ trade_uuid, ...body }) => ({
                url: `/trades/client/${trade_uuid}/close`,
                method: RequestMethods.POST,
                body,
            }),
        }),
    }),
});
export const { useGetTradeListQuery, useGetTradeTrendDataQuery, useCloseTradeServerMutation, useCloseTradeClientMutation, } = tradeApi;
