import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const platformApi = createApi({
    reducerPath: 'platformApi',
    tagTypes: ['platform'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getAvailablePlatformsDict: builder.query({
            query: () => ({
                url: '/platforms',
                method: RequestMethods.GET,
            }),
            providesTags: ['platform'],
        }),
    }),
});
export const { useGetAvailablePlatformsDictQuery, } = platformApi;
